mapper.sql:
WHERE r.tenant_id=#{tenantId} AND r.family_id=#{familyId}
  AND r.member_id IN #{memberId}
AND r.category_code=#{category}
AND r.data_date>=#{start}
AND r.data_date<=#{end}

mapper.select:

AND member_id IN #{memberId}
AND category_code=#{category}
ORDER BY sort_order,id

SELECT r.id,r.account_id AS accountId,r.member_id AS memberId,r.category_code AS categoryCode,
r.account_name AS accountName,r.current_balance AS currentBalance,r.operation,b.update_date AS date
FROM financial_update_record r
JOIN financial_update_batch b ON b.id=r.batch_id AND b.tenant_id=r.tenant_id AND b.family_id=r.family_id
WHERE r.tenant_id=#{tenantId} AND r.family_id=#{familyId}
AND r.account_id IN (
SELECT account_id FROM financial_update_record
WHERE tenant_id=#{tenantId} AND family_id=#{familyId} AND member_id IN #{memberId}
)
ORDER BY b.update_date,r.id

SELECT DISTINCT snapshot_date AS date FROM financial_snapshot
WHERE tenant_id=#{tenantId} AND family_id=#{familyId} AND member_id IN #{memberId}
ORDER BY snapshot_date


AND member_id IN #{memberId}
AND category_code<>'fixed'
ORDER BY member_id,sort_order,id

SELECT snapshot_date AS date,SUM(liquid_amount) AS liquid,SUM(fixed_amount) AS fixed,
SUM(investment_amount) AS investment,SUM(receivable_amount) AS receivable,SUM(liability_amount) AS liability
FROM financial_snapshot WHERE tenant_id=#{tenantId} AND family_id=#{familyId} AND member_id IN #{memberId}
AND snapshot_date>=#{start}
AND snapshot_date<=#{end}
GROUP BY snapshot_date ORDER BY snapshot_date
